import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 책정임금 암호화 키와 방식(pgcrypto 대칭 암호화 + base64). 실제 키는 운영 설정으로 교체해야 한다.
const WAGE_KEY = 'wage-amount-key';
// 가정: 변경 비율은 퍼센트 단위다 (10 = 10% 인상, -5 = 5% 인하).
const RATE_IS_PERCENT = 100;

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

function toInt(v: unknown): number | null {
  if (isBlank(v)) return null;
  const n = Number(v);
  return Number.isInteger(n) ? n : null;
}

@Controller('api/v1')
export class FnSfr02103Controller {
  @Post('/employee-wages/bulk-update')
  @HttpCode(200)
  async bulkUpdateEmployeeWages(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);

    const rawIds = data['employeeIds'];
    if (!Array.isArray(rawIds) || rawIds.length === 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경 대상 임직원을 한 명 이상 선택해 주세요.');
    }
    const ids: number[] = [];
    for (const raw of rawIds) {
      const id = toInt(raw);
      if (id === null) {
        throw new ApiError(400, 'VALIDATION_FAILED', '임직원 ID 형식이 올바르지 않습니다.');
      }
      if (!ids.includes(id)) ids.push(id);
    }

    const effectiveDate = data['effectiveDate'];
    if (typeof effectiveDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(effectiveDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경 효력일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }

    const hasAmount = !isBlank(data['changeAmount']);
    const hasRate = !isBlank(data['changeRate']);
    if (hasAmount === hasRate) {
      throw new ApiError(422, 'INVALID_WAGE_CHANGE_VALUE', '변경 금액 또는 변경 비율 중 하나만 입력해 주세요.');
    }
    const changeValue = Number(hasAmount ? data['changeAmount'] : data['changeRate']);
    if (!Number.isFinite(changeValue)) {
      throw new ApiError(422, 'INVALID_WAGE_CHANGE_VALUE', '변경 값이 올바른 숫자가 아닙니다.');
    }

    return transaction(async (db) => {
      for (const id of ids) {
        const found = await db.query(
          `SELECT employee_id AS "employeeId" FROM employee WHERE employee_id = CAST(:id AS bigint)`,
          { id: String(id) },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '대상 임직원이 존재하지 않습니다.');
        }
      }

      let updatedCount = 0;
      for (const id of ids) {
        const current = await db.query(
          `SELECT salary_step_id AS "salaryStepId",
                  CAST(pgp_sym_decrypt(decode(wage_amount_enc, 'base64'), :key) AS numeric) AS "amount"
             FROM employee_wage
            WHERE employee_id = CAST(:id AS bigint)
              AND effective_date <= CAST(:effectiveDate AS date)
            ORDER BY effective_date DESC
            LIMIT 1`,
          { id: String(id), effectiveDate, key: WAGE_KEY },
        );
        // 가정: 현재 책정임금이 없는 임직원은 계산 기준이 없어 변경하지 않는다.
        if (current.length === 0) continue;

        const before = Number(current[0]['amount']);
        const after = hasAmount
          ? before + changeValue
          : before * (1 + changeValue / RATE_IS_PERCENT);
        const rounded = Math.round(after * 100) / 100;
        if (!Number.isFinite(rounded) || rounded < 0) {
          throw new ApiError(422, 'INVALID_WAGE_CHANGE_VALUE', '변경 후 책정임금이 0보다 작아 변경할 수 없습니다.');
        }

        const saved = await db.query(
          `INSERT INTO employee_wage (employee_id, salary_step_id, effective_date, wage_amount_enc, created_at, updated_at)
           VALUES (CAST(:id AS bigint), CAST(:stepId AS bigint), CAST(:effectiveDate AS date),
                   encode(pgp_sym_encrypt(CAST(:amount AS text), :key), 'base64'), now(), now())
           ON CONFLICT (employee_id, effective_date)
           DO UPDATE SET wage_amount_enc = EXCLUDED.wage_amount_enc, updated_at = now()
           RETURNING employee_wage_id AS "employeeWageId"`,
          {
            id: String(id),
            stepId: current[0]['salaryStepId'] === null ? null : String(current[0]['salaryStepId']),
            effectiveDate,
            amount: String(rounded),
            key: WAGE_KEY,
          },
        );
        updatedCount += 1;

        await db.execute(
          `INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, created_at, updated_at)
           VALUES (CAST(:userId AS bigint), 'employee_wage', CAST(:targetId AS bigint), '일괄 변경', now(), :content, now(), now())`,
          {
            userId: user.id,
            targetId: String(saved[0]['employeeWageId']),
            content: '책정임금 변경: ' + String(before) + ' -> ' + String(rounded) + ' (적용일 ' + effectiveDate + ')',
          },
        );
      }
      return { updatedCount };
    });
  }

  @Get('/employee-wages')
  async listEmployeeWages(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const query = checks.queryOf(req.query);

    const pageNo = isBlank(query['page']) ? 0 : Number(query['page']);
    let size = isBlank(query['size']) ? 20 : Number(query['size']);
    if (!Number.isInteger(pageNo) || pageNo < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 쪽 크기가 올바르지 않습니다.');
    }
    if (size > 200) size = 200;

    let departmentId: string | null = null;
    if (!isBlank(query['departmentId'])) {
      const dep = toInt(query['departmentId']);
      if (dep === null) {
        throw new ApiError(400, 'VALIDATION_FAILED', '부서 조건이 올바르지 않습니다.');
      }
      departmentId = String(dep);
    }

    return transaction(async (db) => {
      const params = { departmentId, limit: String(size), offset: String(pageNo * size) };
      // 가정: 현황은 임직원별 가장 최근 적용일의 책정임금이다.
      const from = `FROM employee_wage w
        JOIN employee e ON e.employee_id = w.employee_id
        WHERE w.effective_date = (SELECT max(x.effective_date) FROM employee_wage x WHERE x.employee_id = w.employee_id)
          AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))`;

      const items = await db.query(
        `SELECT w.employee_id AS "employeeId",
                e.name AS "employeeName",
                w.effective_date AS "effectiveDate",
                w.wage_amount_enc AS "wageAmountEnc"
         ${from}
         ORDER BY e.name, w.employee_id
         LIMIT CAST(:limit AS bigint) OFFSET CAST(:offset AS bigint)`,
        params,
      );
      const counted = await db.query(
        `SELECT COUNT(*) AS "total" ${from}`,
        { departmentId },
      );

      await db.execute(
        `INSERT INTO personal_info_access_log (employee_id, target_employee_id, target_info_type, access_type, accessed_at, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), NULL, '책정임금', '조회', now(), now(), now())`,
        { userId: user.id },
      );

      return { items, page: pageNo, size, total: Number(counted[0]['total']) };
    });
  }
}

