import { useState } from 'react';
import {
  call, useData, Band, Filters, Field, DataTable, Pager, Drawer, Form,
  LookupSelect, RefName, DateText, DateInput, NumberInput, Select, Page, Row, PageProps,
} from '../kit';

export default function FnSfr02103Page({ role, notify }: PageProps) {
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [applied, setApplied] = useState<number | string>('');
  const [pageNo, setPageNo] = useState(0);
  const [open, setOpen] = useState(false);
  const [employeeIds, setEmployeeIds] = useState<number[]>([]);
  const [picker, setPicker] = useState<number | string>('');
  const [mode, setMode] = useState('amount');
  const [changeValue, setChangeValue] = useState<number | string>('');
  const [effectiveDate, setEffectiveDate] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/employee-wages', role, undefined, { departmentId: applied, page: pageNo, size: 20 }),
    [applied, pageNo],
  );

  function openDrawer() {
    setEmployeeIds([]);
    setPicker('');
    setMode('amount');
    setChangeValue('');
    setEffectiveDate('');
    setOpen(true);
  }

  function addEmployee(v: number | string) {
    if (typeof v === 'number' && !employeeIds.includes(v)) {
      setEmployeeIds([...employeeIds, v]);
    }
    setPicker('');
  }

  async function submit() {
    if (employeeIds.length === 0) throw new Error('변경 대상 임직원을 한 명 이상 추가해 주세요.');
    if (changeValue === '') throw new Error('변경 값을 입력해 주세요.');
    if (!effectiveDate) throw new Error('변경 효력일을 입력해 주세요.');
    const body: Row = { employeeIds, effectiveDate };
    if (mode === 'amount') body.changeAmount = changeValue;
    else body.changeRate = changeValue;
    const res = await call<Row>('POST', '/employee-wages/bulk-update', role, body);
    setOpen(false);
    notify('책정임금 ' + String(res.updatedCount) + '건을 변경했습니다.');
    setPageNo(0);
    list.reload();
  }

  return (
    <div>
      <h1>책정임금 현황</h1>
      <Filters
        onSearch={() => { setPageNo(0); setApplied(departmentId); }}
        onReset={() => { setDepartmentId(''); setApplied(''); setPageNo(0); }}
      >
        <Field label="부서 조건">
          <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} placeholder="전체 부서" />
        </Field>
      </Filters>
      <Band total={list.data?.total}>
        <button onClick={openDrawer}>책정임금 일괄 변경</button>
      </Band>
      {list.error ? <p>{list.error}</p> : null}
      <DataTable
        columns={[
          { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
          { key: 'employeeName', label: '임직원명' },
          { key: 'effectiveDate', label: '적용일', render: (r) => <DateText value={r.effectiveDate} /> },
          { key: 'wageAmountEnc', label: '책정임금(암호화)', render: () => <span>암호화되어 저장됨</span> },
        ]}
        rows={list.data?.items ?? []}
        empty="조회된 책정임금이 없습니다. 조건을 바꾸어 다시 조회해 주세요."
      />
      <Pager page={pageNo} size={list.data?.size ?? 20} total={list.data?.total ?? 0} onPage={setPageNo} />
      {open ? (
        <Drawer title="책정임금 일괄 변경" onClose={() => setOpen(false)}>
          <Form
            onSubmit={submit}
            submit="일괄 변경"
            note="변경 후에는 선택한 임직원의 책정임금이 효력일 기준으로 새로 기록되고 변경 이력이 남습니다."
          >
            <Field label="변경 대상 임직원 추가" required wide>
              <LookupSelect table="employee" role={role} value={picker} onChange={addEmployee} placeholder="임직원 선택" />
            </Field>
            <Field label="선택한 임직원" wide>
              <div>
                {employeeIds.length === 0 ? <span>아직 추가한 임직원이 없습니다.</span> : null}
                {employeeIds.map((id) => (
                  <span key={id}>
                    <RefName table="employee" role={role} value={id} />
                    <button type="button" className="ghost" onClick={() => setEmployeeIds(employeeIds.filter((x) => x !== id))}>
                      빼기
                    </button>
                  </span>
                ))}
              </div>
            </Field>
            <Field label="변경 방식" required>
              <Select
                value={mode}
                onChange={setMode}
                options={[['amount', '변경 금액'], ['rate', '변경 비율(%)']]}
              />
            </Field>
            <Field label={mode === 'amount' ? '변경 금액' : '변경 비율'} required hint={mode === 'amount' ? '현재 책정임금에 더할 금액입니다.' : '퍼센트로 입력합니다. 예: 5'}>
              <NumberInput value={changeValue} onChange={setChangeValue} />
            </Field>
            <Field label="변경 효력일" required>
              <DateInput value={effectiveDate} onChange={setEffectiveDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
